{
  "headline": "Prioritize indoor air and limit outdoor exposure",
  "summary": "Today's air quality is {{level.name}} with current AQI {{aqi.now}}. Focus on indoor filtration and consider shifting outdoor activities to cleaner windows.",
  "cards": [
    {
      "actionId": "diy_box_fan_filter",
      "title": "Build a DIY Box Fan Air Filter",
      "why": "A simple, low-cost filter can significantly reduce indoor PM2.5, offering up to {{impact.diy_box_fan_filter.pct}} reduction.",
      "when": "Set up and run continuously indoors.",
      "steps": [
        "Attach a MERV-13 or HEPA filter to a box fan.",
        "Ensure a good seal around the filter.",
        "Run the fan on a medium setting."
      ]
    },
    {
      "actionId": "shift_exercise_to_best_window",
      "title": "Shift Exercise to the Best Air Quality Window",
      "why": "Exercising outdoors during cleaner periods can reduce exposure by {{impact.shift_exercise_to_best_window.pct}}.",
      "when": "Schedule outdoor exercise between {{best.start}} and {{best.end}}.",
      "steps": [
        "Check the air quality forecast daily.",
        "Plan outdoor activities for the identified best window."
      ]
    },
    {
      "actionId": "avoid_indoor_smoke_sources",
      "title": "Avoid Indoor Smoke Sources",
      "why": "Preventing indoor smoke from cooking or burning can reduce PM2.5 exposure by {{impact.avoid_indoor_smoke_sources.pct}}.",
      "when": "Always, but especially when outdoor air is poor.",
      "steps": [
        "Use kitchen exhaust fans when cooking.",
        "Avoid burning incense or candles indoors.",
        "Ensure no smoking indoors."
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Advocate for No Burning in the Community",
      "why": "Community-wide efforts to reduce burning can lead to widespread air quality improvements.",
      "when": "Discuss with neighbors and community leaders.",
      "steps": [
        "Raise awareness about the health impacts of burning.",
        "Encourage alternative heating and cooking methods."
      ]
    },
    {
      "actionId": "damp_mop_dont_sweep",
      "title": "Damp Mop Instead of Sweeping",
      "why": "This method captures fine dust particles, reducing indoor PM2.5 by {{impact.damp_mop_dont_sweep.pct}}.",
      "when": "For regular floor cleaning.",
      "steps": [
        "Use a damp cloth or mop.",
        "Avoid dry sweeping which can re-suspend dust."
      ]
    },
    {
      "actionId": "errands_in_best_window",
      "title": "Run Errands During the Best Air Quality Window",
      "why": "Minimizing time spent outdoors during poor air quality can reduce overall exposure.",
      "when": "Plan outdoor errands for {{best.start}} to {{best.end}}.",
      "steps": [
        "Consolidate errands to minimize trips.",
        "Check air quality before leaving home."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "child",
      "note": "Limit strenuous outdoor activities for children when air quality is {{level.name}}."
    },
    {
      "group": "adult",
      "note": "Consider reducing time spent in high-traffic areas outdoors."
    }
  ],
  "tradeoffs": [
    "Building a DIY filter requires some effort but offers significant indoor air quality improvement.",
    "Shifting errands and exercise to specific windows requires planning but reduces exposure."
  ]
}
